@font-face {
  font-family: 'Bungee';
  src: url('assets/bungee.ttf') format('truetype');
  font-display: swap;
}
@font-face {
  font-family: 'Chakra';
  src: url('assets/chakra-500.ttf') format('truetype');
  font-weight: 500;
  font-display: swap;
}
@font-face {
  font-family: 'Chakra';
  src: url('assets/chakra-700.ttf') format('truetype');
  font-weight: 700;
  font-display: swap;
}

:root {
  --blue: #3dd2ff;
  --blue-deep: #0b78ff;
  --red: #ff406e;
  --red-deep: #ff1d4d;
  --lime: #d9ff45;
  --orange: #ff9a2e;
  --ink: #040714;
  --panel: rgba(6, 11, 28, 0.74);
  --line: rgba(150, 205, 255, 0.22);
  --text: #eaf6ff;
  --muted: #8fa9c9;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--text);
  font-family: 'Chakra', 'Trebuchet MS', sans-serif;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}
button { font-family: inherit; color: inherit; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 48%, rgba(0, 2, 10, 0.42) 100%),
    linear-gradient(to bottom, rgba(0, 3, 12, 0.35), transparent 22%, transparent 72%, rgba(0, 3, 12, 0.5));
  z-index: 2;
}
#speed-lines {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0;
  background:
    repeating-conic-gradient(from 0deg at 50% 52%, transparent 0deg 3.2deg, rgba(170, 235, 255, 0.16) 3.4deg 3.7deg, transparent 4deg 8deg);
  mask-image: radial-gradient(circle at 50% 52%, transparent 0 38%, black 78%);
  -webkit-mask-image: radial-gradient(circle at 50% 52%, transparent 0 38%, black 78%);
  transition: opacity 0.25s ease;
  mix-blend-mode: screen;
}
#hit-flash, #goal-flash {
  position: absolute; inset: 0; pointer-events: none; opacity: 0; z-index: 4;
}
#hit-flash {
  background: radial-gradient(circle at 50% 55%, transparent 30%, rgba(255, 45, 90, 0.55) 100%);
  mix-blend-mode: screen;
}
#goal-flash {
  background: radial-gradient(circle at 50% 50%, rgba(255,255,255,0.95), rgba(120, 220, 255, 0.35) 45%, transparent 78%);
  mix-blend-mode: screen;
}
.flash-on { animation: flashPulse 0.55s ease-out; }
@keyframes flashPulse { 0% { opacity: 0.95; } 100% { opacity: 0; } }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 5; pointer-events: none; }

.hud-top {
  position: absolute;
  top: calc(14px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: stretch;
  gap: 10px;
  filter: drop-shadow(0 8px 22px rgba(0, 0, 0, 0.5));
}
.team-card {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 152px;
  padding: 9px 18px;
  background: linear-gradient(135deg, rgba(8, 16, 38, 0.92), rgba(10, 18, 44, 0.62));
  border: 1px solid var(--line);
  backdrop-filter: blur(10px);
  font-weight: 700;
  letter-spacing: 0.16em;
  clip-path: polygon(12px 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
}
.team-card.blue { border-left: 3px solid var(--blue); color: #d8f6ff; }
.team-card.red { border-right: 3px solid var(--red); color: #ffe0e7; justify-content: flex-end; flex-direction: row; }
.team-card.red .team-badge { order: 3; }
.team-badge {
  width: 26px; height: 26px; border-radius: 8px;
  display: grid; place-items: center;
  font-family: 'Bungee', sans-serif; font-size: 0.8rem;
}
.blue .team-badge { background: linear-gradient(160deg, var(--blue), var(--blue-deep)); color: #02111f; box-shadow: 0 0 18px rgba(61, 210, 255, 0.6); }
.red .team-badge { background: linear-gradient(160deg, var(--red), var(--red-deep)); color: #22030a; box-shadow: 0 0 18px rgba(255, 64, 110, 0.55); }
.team-name { font-size: 0.72rem; opacity: 0.85; }
.score { font-family: 'Bungee', sans-serif; font-size: 1.7rem; line-height: 1; letter-spacing: 0; }
.blue .score { color: var(--blue); text-shadow: 0 0 20px rgba(61, 210, 255, 0.55); }
.red .score { color: var(--red); text-shadow: 0 0 20px rgba(255, 64, 110, 0.55); }

.clock-wrap {
  min-width: 124px;
  padding: 7px 20px 5px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: linear-gradient(180deg, rgba(10, 18, 42, 0.94), rgba(5, 9, 24, 0.86));
  border: 1px solid rgba(210, 235, 255, 0.24);
  clip-path: polygon(10px 0, calc(100% - 10px) 0, 100% 100%, 0 100%);
}
.clock { font-family: 'Bungee', sans-serif; font-size: 1.9rem; line-height: 1; letter-spacing: 0.03em; color: #fff; }
.clock.low { color: var(--lime); animation: clockPulse 1s infinite; }
@keyframes clockPulse { 50% { opacity: 0.55; } }
.clock-label { font-size: 0.55rem; letter-spacing: 0.34em; color: var(--muted); margin-top: 2px; }

.minimap-wrap {
  position: absolute;
  top: calc(100px + var(--safe-top));
  right: calc(22px + var(--safe-right));
  padding: 8px;
  background: linear-gradient(160deg, rgba(7, 14, 34, 0.82), rgba(6, 10, 26, 0.5));
  border: 1px solid var(--line);
  border-radius: 14px;
  backdrop-filter: blur(8px);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.42);
}
#minimap { display: block; width: 132px; height: 192px; border-radius: 8px; }
.minimap-label {
  margin-top: 5px; text-align: center; font-size: 0.5rem; letter-spacing: 0.36em; color: var(--muted);
}

.boost-wrap {
  position: absolute;
  left: calc(26px + var(--safe-left));
  bottom: calc(26px + var(--safe-bottom));
  width: 230px;
  padding: 12px 16px 10px;
  background: linear-gradient(140deg, rgba(7, 14, 34, 0.86), rgba(7, 12, 28, 0.5));
  border: 1px solid var(--line);
  border-left: 3px solid var(--orange);
  border-radius: 12px;
  backdrop-filter: blur(8px);
  clip-path: polygon(0 0, 100% 0, calc(100% - 14px) 100%, 0 100%);
}
.boost-head { display: flex; justify-content: space-between; align-items: baseline; font-size: 0.62rem; letter-spacing: 0.26em; color: #ffd9a8; }
.boost-head #boost-num { font-family: 'Bungee', sans-serif; font-size: 1.05rem; letter-spacing: 0; color: #fff; }
.boost-bar {
  position: relative; height: 12px; margin: 5px 0 6px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 190, 90, 0.24);
  transform: skewX(-18deg);
  overflow: hidden;
}
.boost-fill {
  position: absolute; inset: 0; width: 100%;
  background: linear-gradient(90deg, #ff6a00, #ffb52e 55%, #ffe66b);
  box-shadow: 0 0 16px rgba(255, 150, 40, 0.8);
  transition: width 0.1s linear;
}
.boost-ticks {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 18px, rgba(4, 8, 20, 0.75) 18px 20px);
}
.speed-row { display: flex; align-items: baseline; gap: 6px; font-size: 0.6rem; letter-spacing: 0.2em; color: var(--muted); }
.speed-row #speed { font-family: 'Bungee', sans-serif; font-size: 1.15rem; letter-spacing: 0; color: var(--lime); text-shadow: 0 0 14px rgba(217, 255, 69, 0.45); }

.item-wrap {
  position: absolute;
  right: calc(26px + var(--safe-right));
  bottom: calc(26px + var(--safe-bottom));
  width: 124px;
  display: flex; flex-direction: column; align-items: center; gap: 5px;
}
.item-label { font-size: 0.55rem; letter-spacing: 0.32em; color: var(--muted); }
.item-slot {
  position: relative;
  width: 88px; height: 88px;
  display: grid; place-items: center;
  background:
    radial-gradient(circle at 50% 30%, rgba(255, 255, 255, 0.16), transparent 62%),
    linear-gradient(150deg, rgba(18, 30, 64, 0.95), rgba(5, 10, 26, 0.86));
