Oops I wrote a bogus textureFromCanvas using window.THREE. Fix it to import CanvasTexture from three. utils.js can import three. Let's rewrite the texture helper properly:

```js
import { CanvasTexture, SRGBColorSpace, RepeatWrapping } from 'three';
export function textureFromCanvas(canvas, renderer, {srgb=true, repeat=null}={}) {
 const texture = new CanvasTexture(canvas);
 if (srgb) texture.colorSpace = SRGBColorSpace;
 if (repeat) { texture.wrapS = texture.wrapT = RepeatWrapping; texture.repeat.set(...)}
 if (renderer) texture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
 return texture;
}
```
Also fix shade maybe unused. Let's edit.

