const forward = new Vector3(Math.sin(this.yaw),0,Math.cos(this.yaw));
const right = new Vector3(Math.cos(this.yaw),0,-Math.sin(this.yaw));
let vF = this.vel.dot(forward), vR = this.vel.dot(right);
const wasGrounded = this.grounded;
if (this.grounded) {
   if (spinoutTime<=0) {
     if (throttle>0) vF += 36*dt;
     else if (throttle<0) { if (vF>2) vF -= 52*dt; else vF -= 24*dt; }
     else vF *= exp(-1.4*dt);
     // boost
     if (this.controls.boost && this.boost>0.5) { vF += 62*dt; this.boost = max(0, boost-32*dt); this.boosting = true; } else this.boosting=false;
     if (boostTime>0) { vF += 46*dt; }
   } else {
     this.boosting=false;
     vF *= exp(-2.2*dt);
   }
   // steering
   const speedFactor = clamp(Math.abs(vF)/7, 0.18, 1);
   if (spinout<=0) this.yaw += steer * 2.35 * speedFactor * dt * (vF < -0.5 ? -1 : 1) * (controls.drift?1.25:1);
   // lateral grip
   vR *= Math.exp(-(controls.drift?2.8:10)*dt);
   // drag
   vF *= Math.exp(-0.24*dt);
} else {
   // air
   vF += throttle * 8 * dt;
   vR += steer * 6 * dt;
   vF *= exp(-0.08*dt);
   vR *= exp(-0.5*dt);
   if (spinout<=0) this.yaw += steer * 1.3 * dt;
   this.boosting = false;
}
// clamp
let cap = this.getMaxSpeed();
if (vF > cap) vF = damp(vF, cap, 3.5, dt);
if (vF < -20) vF = -20;
// rebuild
this.vel.x = forward.x*vF + right.x*vR;
this.vel.z = forward.z*vF + right.z*vR;
// gravity
if (!this.grounded) this.vel.y -= ARENA.gravity*dt;
// integrate
this.pos.addScaledVector(this.vel, dt);
// floor
