import { clamp } from './utils.js';

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noiseBuffer = null;
    this.engine = null;
    this.boostNoise = null;
    this.crowd = null;
    this.started = false;
  }

  init() {
    if (this.started) {
      if (this.ctx?.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      const compressor = this.ctx.createDynamicsCompressor();
      compressor.threshold.value = -16;
      compressor.knee.value = 18;
      compressor.ratio.value = 6;
      compressor.attack.value = 0.004;
      compressor.release.value = 0.22;
      this.master.connect(compressor);
      compressor.connect(this.ctx.destination);

      this.noiseBuffer = this.ctx.createBuffer(1, this.ctx.sampleRate * 2, this.ctx.sampleRate);
      const data = this.noiseBuffer.getChannelData(0);
      for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;

      this.createEngine();
      this.createCrowd();
      this.started = true;
    } catch (error) {
      console.warn('Audio unavailable', error);
    }
  }

  createEngine() {
    const ctx = this.ctx;
    const out = ctx.createGain();
    out.gain.value = 0;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 520;
    filter.Q.value = 2.5;

    const oscA = ctx.createOscillator();
    oscA.type = 'sawtooth';
    oscA.frequency.value = 48;
    const oscB = ctx.createOscillator();
    oscB.type = 'square';
    oscB.frequency.value = 96;

    const gainA = ctx.createGain();
    gainA.gain.value = 0.55;
    const gainB = ctx.createGain();
    gainB.gain.value = 0.2;

    oscA.connect(gainA).connect(filter);
    oscB.connect(gainB).connect(filter);
    filter.connect(out).connect(this.master);
    oscA.start();
    oscB.start();

    this.engine = { out, filter, oscA, oscB };

    const boost = ctx.createBufferSource();
    boost.buffer = this.noiseBuffer;
    boost.loop = true;
    const boostFilter = ctx.createBiquadFilter();
    boostFilter.type = 'bandpass';
    boostFilter.frequency.value = 900;
    boostFilter.Q.value = 0.7;
    const boostGain = ctx.createGain();
    boostGain.gain.value = 0;
    boost.connect(boostFilter).connect(boostGain).connect(this.master);
    boost.start();
    this.boostNoise = { gain: boostGain, filter: boostFilter };
  }

  createCrowd() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 620;
    filter.Q.value = 0.45;
    const gain = ctx.createGain();
    gain.gain.value = 0.028;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    this.crowd = { gain, filter };
  }

  setEngine(speed, boosting, throttle, active) {
    if (!this.engine) return;
    const t = this.ctx.currentTime;
    const target = active ? clamp(0.025 + speed * 0.0015 + Math.abs(throttle) * 0.02, 0, 0.14) : 0;
    this.engine.out.gain.setTargetAtTime(target, t, 0.08);
    this.engine.oscA.frequency.setTargetAtTime(42 + speed * 2.1 + (boosting ? 28 : 0), t, 0.07);
    this.engine.oscB.frequency.setTargetAtTime(84 + speed * 4.1 + (boosting ? 55 : 0), t, 0.07);
    this.engine.filter.frequency.setTargetAtTime(380 + speed * 22 + (boosting ? 900 : 0), t, 0.1);
    if (this.boostNoise) {
      this.boostNoise.gain.gain.setTargetAtTime(boosting ? 0.13 : 0, t, 0.05);
      this.boostNoise.filter.frequency.setTargetAtTime(700 + speed * 12, t, 0.1);
    }
  }

  tone({ freq = 440, endFreq = null, dur = 0.2, type = 'sine', vol = 0.2, delay = 0, filter = null }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t0 + dur);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, t0);
    gain.gain.linearRampToValueAtTime(vol, t0 + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    let node = osc;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = filter.type || 'lowpass';
      f.frequency.value = filter.freq || 1000;
      f.Q.value = filter.q || 1;
      node.connect(f);
      node = f;
    }
    node.connect(gain).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  noise({ dur = 0.2, vol = 0.2, freq = 800, q = 1, type = 'bandpass', delay = 0, sweep = null }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t0);
    if (sweep) filter.frequency.exponentialRampToValueAtTime(Math.max(40, sweep), t0 + dur);
    filter.Q.value = q;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  click() {
    this.tone({ freq: 620, endFreq: 880, dur: 0.08, type: 'triangle', vol: 0.12 });
  }

  countdown(final = false) {
    this.tone({ freq: final ? 880 : 520, dur: final ? 0.4 : 0.14, type: 'square', vol: 0.12, filter: { type: 'lowpass', freq: 2400 } });
  }

  go() {
    this.tone({ freq: 440, dur: 0.5, type: 'sawtooth', vol: 0.16, filter: { type: 'lowpass', freq: 1800 } });
    this.tone({ freq: 660, dur: 0.5, type: 'sawtooth', vol: 0.12, delay: 0.02, filter: { type: 'lowpass', freq: 2000 } });
    this.tone({ freq: 880, dur: 0.5, type: 'triangle', vol: 0.1, delay: 0.04 });
    this.cheer(0.7);
  }

  hit(power = 1) {
    const p = clamp(power, 0.3, 1.8);
    this.noise({ dur: 0.12 + p * 0.1, vol: 0.18 * p, freq: 1400, q: 0.8, sweep: 300 });
    this.tone({ freq: 120, endFreq: 45, dur: 0.16 + p * 0.1, type: 'sine', vol: 0.25 * p });
    this.tone({ freq: 320, endFreq: 180, dur: 0.07, type: 'square', vol: 0.06 * p });
  }

  wallHit() {
    this.noise({ dur: 0.1, vol: 0.1, freq: 900, q: 1.5 });
  }

  jump() {
    this.tone({ freq: 300, endFreq: 620, dur: 0.12, type: 'triangle', vol: 0.09 });
  }

  flip() {
    this.tone({ freq: 420, endFreq: 900, dur: 0.18, type: 'sawtooth', vol: 0.07, filter: { type: 'lowpass', freq: 1800 } });
    this.noise({ dur: 0.2, vol: 0.06, freq: 1200, q: 1, sweep: 500 });
  }

  land() {
    this.tone({ freq: 90, endFreq: 45, dur: 0.12, type: 'sine', vol: 0.15 });
  }

  pickup() {
    [660, 880, 1174].forEach((f, i) => this.tone({ freq: f, dur: 0.12, type: 'triangle', vol: 0.1, delay: i * 0.055 }));
    this.tone({ freq: 1760, dur: 0.22, type: 'sine', vol: 0.05, delay: 0.16 });
  }

  itemUse(type) {
    if (type === 'mushroom') {
      this.noise({ dur: 0.5, vol: 0.16, freq: 500, q: 0.7, sweep: 2600 });
      this.tone({ freq: 180, endFreq: 520, dur: 0.4, type: 'sawtooth', vol: 0.1, filter: { type: 'lowpass', freq: 1600 } });
    } else if (type === 'green' || type === 'red') {
      this.tone({ freq: type === 'red' ? 540 : 700, endFreq: 160, dur: 0.24, type: 'square', vol: 0.09, filter: { type: 'lowpass', freq: 2200 } });
      this.noise({ dur: 0.3, vol: 0.1, freq: 1800, q: 1.2, sweep: 500 });
    } else if (type === 'banana') {
      this.tone({ freq: 320, endFreq: 120, dur: 0.18, type: 'triangle', vol: 0.12 });
      this.tone({ freq: 180, endFreq: 80, dur: 0.12, type: 'sine', vol: 0.1, delay: 0.08 });
    } else if (type === 'star') {
      [880, 1108, 1318, 1760].forEach((f, i) => this.tone({ freq: f, dur: 0.28, type: 'triangle', vol: 0.08, delay: i * 0.07 }));
    } else if (type === 'lightning') {
      this.noise({ dur: 0.45, vol: 0.22, freq: 2400, q: 0.6, sweep: 120 });
      this.tone({ freq: 900, endFreq: 90, dur: 0.4, type: 'sawtooth', vol: 0.12 });
    } else if (type === 'bomb') {
      this.tone({ freq: 220, endFreq: 440, dur: 0.25, type: 'triangle', vol: 0.08 });
      this.noise({ dur: 0.12, vol: 0.06, freq: 1200, q: 1 });
    }
  }

  explosion() {
    this.noise({ dur: 0.8, vol: 0.32, freq: 900, q: 0.5, sweep: 60 });
    this.tone({ freq: 90, endFreq: 28, dur: 0.7, type: 'sine', vol: 0.35 });
    this.tone({ freq: 240, endFreq: 50, dur: 0.5, type: 'sawtooth', vol: 0.12, filter: { type: 'lowpass', freq: 800 } });
    this.cheer(0.25);
  }

  hurt() {
    this.tone({ freq: 380, endFreq: 70, dur: 0.5, type: 'sawtooth', vol: 0.12, filter: { type: 'lowpass', freq: 900 } });
    this.noise({ dur: 0.3, vol: 0.1, freq: 700, q: 0.8, sweep: 200 });
  }

  botHit() {
    this.tone({ freq: 260, endFreq: 90, dur: 0.2, type: 'square', vol: 0.05, filter: { type: 'lowpass', freq: 800 } });
  }

  star() {
    [523, 659, 784, 1046, 1318].forEach((f, i) => this.tone({ freq: f, dur: 0.3, type: 'triangle', vol: 0.08, delay: i * 0.06 }));
  }

  goal() {
    if (!this.ctx || this.muted) return;
    const notes = [196, 246.9, 293.7, 392];
    notes.forEach((f, i) => {
      this.tone({ freq: f, dur: 1.3, type: 'sawtooth', vol: 0.12, delay: i * 0.06, filter: { type: 'lowpass', freq: 1200 } });
      this.tone({ freq: f * 2, dur: 1.1, type: 'square', vol: 0.04, delay: i * 0.06, filter: { type: 'lowpass', freq: 1600 } });
    });
    this.noise({ dur: 0.6, vol: 0.12, freq: 300, q: 0.6, sweep: 900 });
    this.cheer(1.3);
  }

  whistle() {
    this.tone({ freq: 1800, endFreq: 2100, dur: 0.3, type: 'sine', vol: 0.09 });
    this.tone({ freq: 2100, endFreq: 1800, dur: 0.3, type: 'sine', vol: 0.07, delay: 0.18 });
  }

  cheer(amount = 0.8) {
    if (!this.crowd) return;
    const t = this.ctx.currentTime;
    this.crowd.gain.gain.cancelScheduledValues(t);
    this.crowd.gain.gain.setValueAtTime(this.crowd.gain.gain.value, t);
    this.crowd.gain.gain.linearRampToValueAtTime(0.09 * amount, t + 0.25);
    this.crowd.gain.gain.exponentialRampToValueAtTime(0.028, t + 2.8);
    this.crowd.filter.frequency.setTargetAtTime(1300, t, 0.3);
    this.crowd.filter.frequency.setTargetAtTime(620, t + 1.5, 1.2);
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.05);
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }
}

import { clamp } from './utils.js';

const KEY_MAP = {
  KeyW: 'up',
  ArrowUp: 'up',
  KeyS: 'down',
  ArrowDown: 'down',
  KeyA: 'left',
  ArrowLeft: 'left',
  KeyD: 'right',
  ArrowRight: 'right',
  ShiftLeft: 'boost',
  ShiftRight: 'boost',
  Space: 'jump',
  KeyE: 'item',
  KeyQ: 'drift',
  KeyC: 'ballcam',
  Escape: 'pause',
  KeyP: 'pause',
  Enter: 'confirm',
};

export class Input {
  constructor() {
    this.keys = new Set();
    this.jumpBuffer = 0;
    this.itemBuffer = 0;
    this.ballCam = true;
    this.stick = { x: 0, y: 0, active: false, pointerId: null };
    this.touch = { boost: false, jump: false, item: false };
    this.gamepad = { throttle: 0, steer: 0, boost: false, jump: false, item: false };
    this.prevPadJump = false;
    this.prevPadItem = false;
    this.callbacks = {};
    this.joystickEl = document.getElementById('joystick');
    this.knobEl = document.getElementById('stick-knob');
    this.bind();
  }

  on(name, fn) {
    this.callbacks[name] = fn;
  }

  bind() {
    window.addEventListener('keydown', (event) => {
      if (event.repeat) {
        if (KEY_MAP[event.code]) event.preventDefault();
        return;
      }
      const action = KEY_MAP[event.code];
      if (!action) return;
      event.preventDefault();
      if (action === 'pause') {
        this.callbacks.pause?.();
        return;
      }
      if (action === 'ballcam') {
        this.ballCam = !this.ballCam;
        this.callbacks.ballcam?.(this.ballCam);
        return;
      }
      if (action === 'confirm') {
        this.callbacks.confirm?.();
        return;
      }
      this.keys.add(action);
      if (action === 'jump') this.jumpBuffer = 0.14;
      if (action === 'item') this.itemBuffer = 0.14;
    });

    window.addEventListener('keyup', (event) => {
      const action = KEY_MAP[event.code];
      if (!action) return;
      event.preventDefault();
      this.keys.delete(action);
    });

    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touch.boost = false;
      this.touch.jump = false;
      this.touch.item = false;
      this.resetStick();
    });

    this.bindJoystick();
    this.bindButton('btn-boost', 'boost');
    this.bindButton('btn-jump', 'jump');
    this.bindButton('btn-item', 'item');

    // don't let the page scroll or zoom during play
    document.addEventListener('gesturestart', (e) => e.preventDefault());
    document.addEventListener('touchmove', (e) => {
      if (e.target.closest('#joystick, .touch-btn, #game')) e.preventDefault();
    }, { passive: false });
  }

  bindJoystick() {
    if (!this.joystickEl) return;
    const el = this.joystickEl;
    const knob = this.knobEl;
    const max = 43;

    const move = (event) => {
      if (event.pointerId !== this.stick.pointerId) return;
      const rect = el.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = event.clientX - cx;
      let dy = event.clientY - cy;
      const len = Math.hypot(dx, dy);
      const clampedLen = Math.min(len, max);
      if (len > 0.001) {
        dx = (dx / len) * clampedLen;
        dy = (dy / len) * clampedLen;
      }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      const nx = dx / max;
      const ny = dy / max;
      this.stick.x = Math.abs(nx) < 0.16 ? 0 : nx;
      this.stick.y = Math.abs(ny) < 0.16 ? 0 : ny;
      this.stick.active = true;
    };

    const end = (event) => {
      if (event.pointerId !== this.stick.pointerId) return;
      this.resetStick();
    };

    el.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      this.stick.pointerId = event.pointerId;
      el.setPointerCapture?.(event.pointerId);
      move(event);
    });
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', end);
    el.addEventListener('pointercancel', end);
    el.addEventListener('lostpointercapture', end);
  }

  resetStick() {
    this.stick.x = 0;
    this.stick.y = 0;
    this.stick.active = false;
    this.stick.pointerId = null;
    if (this.knobEl) this.knobEl.style.transform = 'translate(0px, 0px)';
  }

  bindButton(id, action) {
    const el = document.getElementById(id);
    if (!el) return;
    const press = (event) => {
      event.preventDefault();
      el.setPointerCapture?.(event.pointerId);
      el.classList.add('active');
      this.touch[action] = true;
      if (action === 'jump') this.jumpBuffer = 0.14;
      if (action === 'item') this.itemBuffer = 0.14;
    };
    const release = (event) => {
      event.preventDefault();
      el.classList.remove('active');
      this.touch[action] = false;
    };
    el.addEventListener('pointerdown', press);
    el.addEventListener('pointerup', release);
    el.addEventListener('pointercancel', release);
    el.addEventListener('lostpointercapture', release);
    el.addEventListener('pointerleave', (event) => {
      if (event.buttons === 0) release(event);
    });
  }

  pollGamepad() {
    const pads = navigator.getGamepads?.();
    if (!pads) return;
    let pad = null;
    for (const p of pads) {
      if (p && p.connected) { pad = p; break; }
    }
    if (!pad) {
      this.gamepad.throttle = 0;
      this.gamepad.steer = 0;
      this.gamepad.boost = false;
      this.gamepad.jump = false;
      this.gamepad.item = false;
      return;
    }
    const axes = pad.axes;
    const steer = Math.abs(axes[0] || 0) > 0.16 ? axes[0] : 0;
    const throttle = -(Math.abs(axes[1] || 0) > 0.16 ? axes[1] : 0);
    this.gamepad.steer = steer;
    this.gamepad.throttle = throttle;
    this.gamepad.boost = !!pad.buttons[7]?.pressed || !!pad.buttons[0]?.pressed;
    const jump = !!pad.buttons[0]?.pressed || !!pad.buttons[1]?.pressed;
    const item = !!pad.buttons[2]?.pressed || !!pad.buttons[3]?.pressed;
    if (jump && !this.prevPadJump) this.jumpBuffer = 0.14;
    if (item && !this.prevPadItem) this.itemBuffer = 0.14;
    this.prevPadJump = jump;
    this.prevPadItem = item;
    this.gamepad.jump = jump;
    this.gamepad.item = item;
  }

  update(dt) {
    this.pollGamepad();
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
    this.itemBuffer = Math.max(0, this.itemBuffer - dt);
  }

  getControls() {
    const k = this.keys;
    const up = k.has('up') ? 1 : 0;
    const down = k.has('down') ? 1 : 0;
    const left = k.has('left') ? 1 : 0;
    const right = k.has('right') ? 1 : 0;

    let throttle = up - down;
    let steer = right - left;
    let boost = k.has('boost') || this.touch.boost;
    let jump = k.has('jump') || this.touch.jump || this.jumpBuffer > 0;
    let item = k.has('item') || this.touch.item || this.itemBuffer > 0;
    const drift = k.has('drift');

    if (this.stick.active) {
      throttle += -this.stick.y;
      steer += this.stick.x;
    }
    throttle += this.gamepad.throttle;
    steer += this.gamepad.steer;
    boost = boost || this.gamepad.boost;
    jump = jump || this.gamepad.jump || this.jumpBuffer > 0;
    item = item || this.gamepad.item || this.itemBuffer > 0;

    return {
      throttle: clamp(throttle, -1, 1),
      steer: clamp(steer, -1, 1),
      boost,
      jump,
      item,
      drift,
    };
  }
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { ARENA, ITEMS, ITEM_TABLE, TEAM } from './constants.js';
import { collideArena } from './physics.js';
import { clamp, rand, chance, weightedChoice, makeCanvas, textureFromCanvas, TAU } from './utils.js';

const _v = new THREE.Vector3();

function createQuestionTexture(renderer) {
  const c = makeCanvas(256, 256);
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, 256, 256);
  grad.addColorStop(0, '#8ef4ff');
  grad.addColorStop(0.4, '#6ea8ff');
  grad.addColorStop(0.7, '#c78bff');
  grad.addColorStop(1, '#ff8ad0');
  g.fillStyle = grad;
  g.fillRect(0, 0, 256, 256);
  g.strokeStyle = 'rgba(255,255,255,0.9)';
  g.lineWidth = 6;
  g.strokeRect(8, 8, 240, 240);
  g.fillStyle = '#ffffff';
  g.font = '400 190px Bungee, sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.shadowColor = '#3d7dff';
  g.shadowBlur = 26;
  g.fillText('?', 128, 140);
  return textureFromCanvas(c, renderer);
}

function createShellMesh(color, effects) {
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({
    color,
    emissive: color,
    emissiveIntensity: 0.45,
    metalness: 0.35,
    roughness: 0.32,
  });
  const dome = new THREE.Mesh(new THREE.SphereGeometry(0.68, 22, 14, 0, TAU, 0, Math.PI * 0.62), mat);
  dome.rotation.x = Math.PI;
  dome.position.y = 0.22;
  group.add(dome);
  const belly = new THREE.Mesh(
    new THREE.SphereGeometry(0.66, 20, 10, 0, TAU, Math.PI * 0.52, Math.PI * 0.48),
    new THREE.MeshStandardMaterial({ color: 0xfff3d6, roughness: 0.5, metalness: 0.1 })
  );
  belly.position.y = 0.2;
  group.add(belly);
  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(0.62, 0.09, 8, 28),
    new THREE.MeshBasicMaterial({ color: 0xffffff })
  );
  rim.rotation.x = Math.PI / 2;
  rim.position.y = 0.12;
  group.add(rim);
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: effects.glowTex,
    color,
    transparent: true,
    opacity: 0.55,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  }));
  glow.scale.set(2.8, 2.8, 1);
  group.add(glow);
  return group;
}

function createBombMesh(effects) {
  const group = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.SphereGeometry(0.72, 20, 14),
    new THREE.MeshStandardMaterial({ color: 0x151822, metalness: 0.55, roughness: 0.35 })
  );
  group.add(body);
  const cap = new THREE.Mesh(
    new THREE.CylinderGeometry(0.18, 0.22, 0.3, 8),
    new THREE.MeshStandardMaterial({ color: 0x2b2f3d, metalness: 0.7, roughness: 0.3 })
  );
  cap.position.y = 0.72;
  group.add(cap);
  const fuse = new THREE.Mesh(
    new THREE.TorusGeometry(0.22, 0.045, 6, 14, Math.PI * 0.9),
    new THREE.MeshBasicMaterial({ color: 0xd7b98b })
  );
  fuse.position.set(0.1, 0.92, 0);
  group.add(fuse);
  const spark = new THREE.Sprite(new THREE.SpriteMaterial({
    map: effects.glowTex,
    color: 0xffd36e,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  }));
  spark.position.set(0.26, 1.02, 0);
  spark.scale.set(1.1, 1.1, 1);
  group.add(spark);
  group.userData.spark = spark;
  return group;
}

function createBananaMesh(effects) {
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({
    color: 0xffe14a,
    emissive: 0xd6a600,
    emissiveIntensity: 0.5,
    metalness: 0.1,
    roughness: 0.45,
  });
  const arc = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.22, 10, 22, Math.PI * 1.05), mat);
  arc.rotation.x = Math.PI / 2;
  arc.rotation.z = Math.PI * 0.5;
  arc.position.y = 0.42;
  group.add(arc);
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 0.3, 6), new THREE.MeshStandardMaterial({ color: 0x8a6b28, roughness: 0.7 }));
  stem.position.set(0.7, 0.52, 0);
  stem.rotation.z = 0.6;
  group.add(stem);
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: effects.glowTex,
    color: 0xffe14a,
    transparent: true,
    opacity: 0.45,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  }));
  glow.position.y = 0.5;
  glow.scale.set(3.2, 3.2, 1);
  group.add(glow);
  return group;
}

export class ItemSystem {
  constructor(scene, renderer, effects, audio, ball) {
    this.scene = scene;
    this.renderer = renderer;
    this.effects = effects;
    this.audio = audio;
    this.ball = ball;
    this.enabled = false;
    this.boxes = [];
    this.projectiles = [];
    this.bananas = [];
    this.callbacks = {};
    this.questionTex = createQuestionTexture(renderer);

    const spawns = [
      [-16, 0], [16, 0],
      [0, -26], [0, 26],
      [-16, -38], [16, 38], [-16, 38], [16, -38],
    ];
    for (const [x, z] of spawns) {
      const group = new THREE.Group();
      group.position.set(x, 2.5, z);

      const boxMat = new THREE.MeshStandardMaterial({
        color: 0x9fe8ff,
        emissive: 0x2f8bff,
        emissiveIntensity: 0.8,
        transparent: true,
        opacity: 0.26,
        metalness: 0.4,
        roughness: 0.15,
        depthWrite: false,
      });
      const cube = new THREE.Mesh(new RoundedBoxGeometry(2.25, 2.25, 2.25, 3, 0.28), boxMat);
      group.add(cube);

      const edges = new THREE.LineSegments(
        new THREE.EdgesGeometry(new RoundedBoxGeometry(2.3, 2.3, 2.3, 2, 0.26)),
        new THREE.LineBasicMaterial({ color: 0xbdf3ff, transparent: true, opacity: 0.9 })
      );
      group.add(edges);

      const question = new THREE.Sprite(new THREE.SpriteMaterial({
        map: this.questionTex,
        transparent: true,
        depthWrite: false,
        toneMapped: false,
      }));
      question.scale.set(1.4, 1.4, 1);
      group.add(question);

      const glow = new THREE.Sprite(new THREE.SpriteMaterial({
        map: effects.glowTex,
        color: 0x6fb8ff,
        transparent: true,
        opacity: 0.5,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }));
      glow.scale.set(5.2, 5.2, 1);
      group.add(glow);

      scene.add(group);
      this.boxes.push({
        group,
        cube,
        question,
        glow,
        base: new THREE.Vector3(x, 2.5, z),
        active: true,
        timer: 0,
        phase: rand(0, TAU),
      });
    }
  }

  on(name, fn) {
    this.callbacks[name] = fn;
  }

  reset() {
    for (const box of this.boxes) {
      box.active = true;
      box.timer = 0;
      box.group.visible = true;
    }
    for (const p of this.projectiles) this.scene.remove(p.mesh);
    for (const b of this.bananas) this.scene.remove(b.mesh);
    this.projectiles.length = 0;
    this.bananas.length = 0;
  }

  update(dt, time, cars) {
    for (const box of this.boxes) {
      if (!box.active) {
        box.timer -= dt;
        if (box.timer <= 0) {
          box.active = true;
          box.group.visible = true;
          this.effects.burst(box.base, 0x8fe8ff, 10, { speed: 5, size: 0.8, life: 0.5, gravity: 0 });
        }
        continue;
      }
      box.group.position.y = box.base.y + Math.sin(time * 2 + box.phase) * 0.35;
      box.group.rotation.y = time * 0.8 + box.phase;
      box.group.rotation.x = Math.sin(time * 0.7 + box.phase) * 0.18;
      box.question.material.rotation = Math.sin(time * 2) * 0.1;
      box.cube.material.emissiveIntensity = 0.55 + Math.sin(time * 3 + box.phase) * 0.3;
      box.glow.material.opacity = 0.3 + Math.sin(time * 2.5 + box.phase) * 0.15;

      if (!this.enabled) continue;
      for (const car of cars) {
        if (car.item) continue;
        const dx = car.pos.x - box.base.x;
        const dz = car.pos.z - box.base.z;
        if (dx * dx + dz * dz < 3.6 * 3.6 && car.pos.y < 4) {
          this.giveItem(car, weightedChoice(ITEM_TABLE));
          box.active = false;
          box.timer = 8;
          box.group.visible = false;
          this.effects.burst(box.base, 0x8fe8ff, 22, { speed: 8, size: 1, life: 0.6, gravity: 1 });
          this.audio.pickup();
          break;
        }
      }
    }

    // projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt;
      p.age += dt;

      if (p.type === 'red' && p.target && p.target.root.visible) {
        _v.copy(p.target.pos).add(new THREE.Vector3(0, 1, 0));
        _v.sub(p.pos);
        const desired = Math.atan2(_v.x, _v.z);
        const current = Math.atan2(p.vel.x, p.vel.z);
        let diff = desired - current;
        while (diff > Math.PI) diff -= TAU;
        while (diff < -Math.PI) diff += TAU;
        const turn = clamp(diff, -3.4 * dt, 3.4 * dt);
        const speed = Math.hypot(p.vel.x, p.vel.z);
        const angle = current + turn;
        p.vel.x = Math.sin(angle) * speed;
        p.vel.z = Math.cos(angle) * speed;
      }

      if (p.gravity) p.vel.y -= p.gravity * dt;
      p.pos.addScaledVector(p.vel, dt);

      if (p.type === 'bomb') {
        if (p.pos.y < 0.7) {
          p.pos.y = 0.7;
          p.vel.y = Math.abs(p.vel.y) * 0.35;
          p.vel.x *= 0.7;
          p.vel.z *= 0.7;
        }
        p.mesh.userData.spark.scale.setScalar(0.8 + Math.sin(p.age * 30) * 0.25);
        if (p.age > p.fuse) {
          this.explode(p.pos, p.owner, cars);
          this.scene.remove(p.mesh);
          this.projectiles.splice(i, 1);
          continue;
        }
        // bomb proximity detonation
        let detonated = false;
        for (const car of cars) {
          if (car === p.owner) continue;
          const dx = car.pos.x - p.pos.x;
          const dz = car.pos.z - p.pos.z;
          if (dx * dx + dz * dz < 2.4 * 2.4) { detonated = true; break; }
        }
        if (detonated) {
          this.explode(p.pos, p.owner, cars);
          this.scene.remove(p.mesh);
          this.projectiles.splice(i, 1);
          continue;
        }
      } else {
        const bounced = collideArena(p.pos, p.vel, 0.62, 0.92, true);
        if (bounced) {
          p.bounces++;
          this.effects.sparkle(p.pos, p.type === 'red' ? 0xff8fa8 : 0x8fffba, 4, 0.6, 0.35);
          this.audio.wallHit();
        }
        if (p.pos.y < 0.62) {
          p.pos.y = 0.62;
          p.vel.y = Math.abs(p.vel.y) * 0.6 + 1;
        }
      }

      // ball interaction
      if (this.ball) {
        const dx = this.ball.pos.x - p.pos.x;
        const dy = this.ball.pos.y - p.pos.y;
        const dz = this.ball.pos.z - p.pos.z;
        if (dx * dx + dy * dy + dz * dz < (ARENA.ballR + 0.7) ** 2 && p.ballCooldown <= 0) {
          p.ballCooldown = 0.25;
          this.ball.vel.addScaledVector(p.vel, 0.22);
          this.ball.vel.y += 2.5;
          this.effects.hit(p.pos, p.type === 'red' ? 0xff6a8c : 0x6aff9a);
        }
      }
      p.ballCooldown = Math.max(0, (p.ballCooldown || 0) - dt);

      // car hits
      let removed = false;
      for (const car of cars) {
        if (car === p.owner || car.team === p.owner.team) continue;
        const dx = car.pos.x - p.pos.x;
        const dy = car.pos.y + 1 - p.pos.y;
        const dz = car.pos.z - p.pos.z;
        if (dx * dx + dy * dy + dz * dz < 2.6 * 2.6) {
          const dir = new THREE.Vector3(p.vel.x, 0, p.vel.z).normalize();
          car.takeHit(dir, p.type === 'red' ? 1.25 : 1);
          this.effects.hit(p.pos, p.type === 'red' ? 0xff406e : 0x35ff88);
          this.scene.remove(p.mesh);
          this.projectiles.splice(i, 1);
          removed = true;
          break;
        }
      }
      if (removed) continue;

      if (p.life <= 0) {
        this.effects.sparkle(p.pos, p.type === 'red' ? 0xff6a8c : 0x6aff9a, 8, 0.8, 0.5);
        this.scene.remove(p.mesh);
        this.projectiles.splice(i, 1);
        continue;
      }

      p.mesh.position.copy(p.pos);
      p.mesh.rotation.y += dt * 12;
      if (Math.random() < 0.6) {
        this.effects.sparkle(p.pos, p.type === 'red' ? 0xff8fa8 : 0x8fffba, 1, 0.65, 0.3);
      }
    }

    // bananas
    for (let i = this.bananas.length - 1; i >= 0; i--) {
      const b = this.bananas[i];
      b.life -= dt;
      b.armTime -= dt;
      b.mesh.rotation.y += dt * 1.5;
      b.mesh.position.y = 0.05 + Math.sin(time * 2 + i) * 0.04;
      if (b.life <= 0) {
        this.scene.remove(b.mesh);
        this.bananas.splice(i, 1);
        continue;
      }
      if (!this.enabled) continue;
      for (const car of cars) {
        if (car === b.owner || car.team === b.owner.team) continue;
        const dx = car.pos.x - b.pos.x;
        const dz = car.pos.z - b.pos.z;
        if (dx * dx + dz * dz < 2.4 * 2.4 && car.pos.y < 2.2) {
          const dir = new THREE.Vector3(dx, 0, dz).normalize();
          car.takeHit(dir, 0.8);
          this.effects.burst(new THREE.Vector3(b.pos.x, 0.8, b.pos.z), 0xffe14a, 18, { speed: 9, size: 0.9, life: 0.6, gravity: 5 });
          this.audio.itemUse('banana');
          this.scene.remove(b.mesh);
          this.bananas.splice(i, 1);
          break;
        }
      }
    }
  }

  giveItem(car, type) {
    car.item = type;
    car.itemAge = 0;
    this.callbacks.pickup?.(car, type);
  }

  useItem(car, cars) {
    if (!car.item) return false;
    const type = car.item;
    car.item = null;
    const forward = car.forward;
    this.callbacks.use?.(car, type);
    this.audio.itemUse(type);

    if (type === 'mushroom') {
      car.boostTime = Math.max(car.boostTime, 2.8);
      car.boost = Math.min(100, car.boost + 45);
      const rear = new THREE.Vector3(car.pos.x - forward.x * 2, car.pos.y + 0.8, car.pos.z - forward.z * 2);
      this.effects.burst(rear, 0xffb23e, 22, { speed: 11, size: 1.2, life: 0.6, gravity: 0 });
      this.effects.ring(new THREE.Vector3(car.pos.x, car.pos.y + 1, car.pos.z), 0xffb23e, 2, 0.3, 7);
    } else if (type === 'star') {
      car.applyStar();
    } else if (type === 'lightning') {
      for (const other of cars) {
        if (other.team !== car.team) other.applyLightning();
      }
      this.callbacks.lightning?.(car);
    } else if (type === 'banana') {
      const pos = new THREE.Vector3(car.pos.x - forward.x * 3.4, 0.05, car.pos.z - forward.z * 3.4);
      const mesh = createBananaMesh(this.effects);
      mesh.position.copy(pos);
      this.scene.add(mesh);
      this.bananas.push({ mesh, pos, owner: car, life: 22, armTime: 0.5 });
    } else if (type === 'bomb') {
      const mesh = createBombMesh(this.effects);
      const pos = new THREE.Vector3(car.pos.x + forward.x * 2.8, 1.1, car.pos.z + forward.z * 2.8);
      mesh.position.copy(pos);
      this.scene.add(mesh);
      this.projectiles.push({
        type: 'bomb',
        mesh,
        pos,
        vel: new THREE.Vector3(forward.x * 28, 10, forward.z * 28),
        life: 4,
        age: 0,
        fuse: 1.5,
        gravity: 22,
        owner: car,
        radius: 0.7,
        bounces: 0,
        ballCooldown: 0,
      });
    } else if (type === 'green' || type === 'red') {
      const color = type === 'green' ? 0x35d96b : 0xff406e;
      const mesh = createShellMesh(color, this.effects);
      const pos = new THREE.Vector3(car.pos.x + forward.x * 2.8, 1, car.pos.z + forward.z * 2.8);
      mesh.position.copy(pos);
      this.scene.add(mesh);
      let target = null;
      if (type === 'red') {
        let best = Infinity;
        for (const other of cars) {
          if (other.team === car.team) continue;
          const dist = other.pos.distanceToSquared(car.pos);
          if (dist < best) { best = dist; target = other; }
        }
      }
      const speed = type === 'green' ? 52 : 44;
      this.projectiles.push({
        type,
        mesh,
        pos,
        vel: new THREE.Vector3(forward.x * speed, 0, forward.z * speed),
        life: type === 'green' ? 6 : 8,
        age: 0,
        gravity: 0,
        owner: car,
        target,
        radius: 0.7,
        bounces: 0,
        ballCooldown: 0,
      });
      this.effects.burst(pos, color, 12, { speed: 6, size: 0.8, life: 0.4, gravity: 0 });
    }
    return true;
  }

  explode(pos, owner, cars) {
    this.effects.explosion(pos, 0xff8a2e);
    this.audio.explosion();
    for (const car of cars) {
      if (car === owner) continue;
      const dx = car.pos.x - pos.x;
      const dy = car.pos.y + 1 - pos.y;
      const dz = car.pos.z - pos.z;
      const dist = Math.hypot(dx, dy, dz);
      if (dist < 10.5) {
        const dir = new THREE.Vector3(dx, 0, dz).normalize();
        const power = 1 + (1 - dist / 10.5) * 1.2;
        car.takeHit(dir, power);
      }
    }
    if (this.ball) {
      const dx = this.ball.pos.x - pos.x;
      const dy = this.ball.pos.y - pos.y;
      const dz = this.ball.pos.z - pos.z;
      const dist = Math.hypot(dx, dy, dz);
      if (dist < 13) {
        const dir = new THREE.Vector3(dx, Math.max(0.4, dy), dz).normalize();
        this.ball.vel.addScaledVector(dir, (1 - dist / 13) * 46 + 12);
      }
    }
    this.callbacks.explosion?.(pos, owner);
  }
}

import * as THREE from 'three';
import { ARENA } from './constants.js';
import { clamp, normalizeAngle, rand, chance } from './utils.js';

const _target = new THREE.Vector3();
const _ballPred = new THREE.Vector3();

export class AIController {
  constructor(car, game, skill = 0.8, seed = Math.random() * 100) {
    this.car = car;
    this.game = game;
    this.skill = skill;
    this.seed = seed;
    this.role = 'attack';
    this.jumpCooldown = 0;
    this.itemDelay = 0;
    this.boostSeekTimer = 0;
    this.thinkTimer = 0;
    this.noise = 0;
  }

  update(dt, time) {
    const car = this.car;
    const game = this.game;
    const controls = car.controls;
    controls.throttle = 0;
    controls.steer = 0;
    controls.boost = false;
    controls.jump = false;
    controls.item = false;
    controls.drift = false;

    if (game.state !== 'playing' || !car.root.visible) return;
    if (car.spinoutTime > 0) return;

    this.jumpCooldown = Math.max(0, this.jumpCooldown - dt);
    this.itemDelay = Math.max(0, this.itemDelay - dt);
    this.boostSeekTimer = Math.max(0, this.boostSeekTimer - dt);
    this.thinkTimer -= dt;
    if (this.thinkTimer <= 0) {
      this.thinkTimer = 0.15 + rand(0, 0.2);
      this.noise = (1 - this.skill) * rand(-0.55, 0.55);
    }

    const ball = game.ball;
    const teammates = game.cars.filter((c) => c.team === car.team);
    const opponents = game.cars.filter((c) => c.team !== car.team);
    const myGoalZ = car.team === 'blue' ? ARENA.halfL : -ARENA.halfL;
    const enemyGoalZ = -myGoalZ;

    let closest = null;
    let closestDist = Infinity;
    for (const c of teammates) {
      const d = c.pos.distanceToSquared(ball.pos);
      if (d < closestDist) { closestDist = d; closest = c; }
    }
    this.role = closest === car ? 'attack' : 'support';

    _ballPred.copy(ball.pos).addScaledVector(ball.vel, 0.28);
    _ballPred.x = clamp(_ballPred.x, -ARENA.halfW + 2, ARENA.halfW - 2);
    _ballPred.z = clamp(_ballPred.z, -ARENA.halfL + 2, ARENA.halfL - 2);

    let targetZ;
    let targetX;
    if (this.role === 'attack') {
      const goalToBallX = _ballPred.x - 0;
      const goalToBallZ = _ballPred.z - enemyGoalZ;
      const len = Math.hypot(goalToBallX, goalToBallZ) || 1;
      const behindX = _ballPred.x + (goalToBallX / len) * 4.4;
      const behindZ = _ballPred.z + (goalToBallZ / len) * 4.4;
      targetX = behindX + this.noise * 5;
      targetZ = behindZ;
      // if we're already goal-side of the ball, still approach from behind
      if (Math.abs(ball.pos.z - car.pos.z) < 5 && Math.abs(ball.pos.x - car.pos.x) < 4) {
        targetX = ball.pos.x;
        targetZ = ball.pos.z;
      }
    } else {
      const defendX = _ballPred.x * 0.32;
      const defendZ = _ballPred.z + (myGoalZ - _ballPred.z) * 0.3;
      targetX = defendX + this.noise * 4;
      targetZ = defendZ;
      if (Math.abs(_ballPred.z - myGoalZ) < 20) {
        targetX = _ballPred.x * 0.55;
        targetZ = myGoalZ - Math.sign(myGoalZ) * 10;
      }
    }

    targetX = clamp(targetX, -ARENA.halfW + 3, ARENA.halfW - 3);
    targetZ = clamp(targetZ, -ARENA.halfL + 3, ARENA.halfL - 3);

    // grab boost when low and the ball is not urgent
    if (car.boost < 26 && this.role === 'support' && this.boostSeekTimer <= 0) {
      let bestPad = null;
      let bestDist = Infinity;
      for (const pad of game.world.pads) {
        if (!pad.active) continue;
        const d = Math.hypot(pad.pos.x - car.pos.x, pad.pos.z - car.pos.z);
        if (d < bestDist && d < 34) { bestDist = d; bestPad = pad; }
      }
      if (bestPad && bestDist < 30) {
        targetX = bestPad.pos.x;
        targetZ = bestPad.pos.z;
        this.boostSeekTimer = 2.5;
      }
    }

    // avoid parking in our own net
    if (Math.abs(car.pos.z - myGoalZ) < 9 && Math.abs(car.pos.x) < ARENA.goalHalfW + 2) {
      targetZ = myGoalZ - Math.sign(myGoalZ) * 14;
    }

    _target.set(targetX, 0, targetZ);
    const dx = _target.x - car.pos.x;
    const dz = _target.z - car.pos.z;
    const distance = Math.hypot(dx, dz);
    const desiredYaw = Math.atan2(dx, dz);
    const diff = normalizeAngle(desiredYaw - car.yaw);

    const aggression = this.role === 'attack' ? 1 : 0.75;
    let steer = clamp(diff * 2.2 + this.noise * 0.8, -1, 1);
    let throttle = distance > 4 ? 1 : 0.25;

    if (Math.abs(diff) > 1.75 && distance < 10) {
      throttle = -0.7;
      steer = clamp(-diff * 1.5, -1, 1);
    }

    if (Math.abs(diff) < 0.32 && distance > 15 && car.boost > 12 && this.role === 'attack') {
      controls.boost = true;
    }
    if (Math.abs(diff) > 0.65 && car.speed > 18) controls.drift = true;

    // ball attack: charge when lined up with the goal
    const distToBall = car.pos.distanceTo(ball.pos);
    if (this.role === 'attack' && distToBall < 14) {
      const goalDir = new THREE.Vector3(0, 0, enemyGoalZ).sub(ball.pos).normalize();
      const carToBall = new THREE.Vector3().subVectors(ball.pos, car.pos).normalize();
      const alignment = goalDir.dot(carToBall);
      if (alignment > 0.25 && car.boost > 8) controls.boost = true;
      if (Math.abs(diff) < 0.5) throttle = 1;
    }

    // jumping for aerial balls
    if (this.jumpCooldown <= 0 && distToBall < 7.5 && ball.pos.y > 3.6 && car.grounded) {
      if (chance(0.35 + this.skill * 0.4)) {
        controls.jump = true;
        this.jumpCooldown = 0.7;
      }
    }
    if (!car.grounded && this.jumpCooldown <= 0 && distToBall < 5.5 && ball.pos.y > car.pos.y + 1.6 && car.jumps < 2) {
      controls.jump = true;
      this.jumpCooldown = 0.9;
    }

    // items
    if (car.item && this.itemDelay <= 0) {
      const type = car.item;
      const nearestEnemy = opponents.reduce((best, o) => {
        const d = o.pos.distanceToSquared(car.pos);
        return d < best.d ? { o, d } : best;
      }, { o: null, d: Infinity }).o;

      let use = false;
      if (type === 'mushroom' || type === 'star') {
        use = distToBall > 10 || car.boost < 35;
      } else if (type === 'green' || type === 'red') {
        if (nearestEnemy) {
          const toEnemy = new THREE.Vector3().subVectors(nearestEnemy.pos, car.pos);
          const dist = toEnemy.length();
          const fwd = car.forward;
          const dot = toEnemy.normalize().dot(fwd);
          use = dist < 42 && dot > 0.45;
        }
      } else if (type === 'banana') {
        const chaser = opponents.find((o) => {
          const rel = new THREE.Vector3().subVectors(o.pos, car.pos);
          return rel.length() < 16 && rel.normalize().dot(car.forward) < -0.2;
        });
        use = !!chaser || chance(0.25);
      } else if (type === 'bomb') {
        use = distToBall < 26 || (nearestEnemy && nearestEnemy.pos.distanceTo(car.pos) < 18);
      } else if (type === 'lightning') {
        use = true;
      }

      if (use) {
        game.items.useItem(car, game.cars);
        this.itemDelay = 0.8 + rand(0, 0.8);
      } else {
        this.itemDelay = 0.35;
      }
    }

    controls.steer = steer;
    controls.throttle = throttle * aggression;
    if (car.spinoutTime > 0) {
      controls.throttle = 0;
      controls.steer = 0;
      controls.boost = false;
    }
  }
}

import { ARENA, ITEMS, TEAM } from './constants.js';
import { clamp, formatTime, TAU } from './utils.js';

export class HUD {
  constructor() {
    this.el = {
      hud: document.getElementById('hud'),
      scoreBlue: document.getElementById('score-blue'),
      scoreRed: document.getElementById('score-red'),
      clock: document.getElementById('clock'),
      clockLabel: document.getElementById('clock-label'),
      boostFill: document.getElementById('boost-fill'),
      boostNum: document.getElementById('boost-num'),
      speed: document.getElementById('speed'),
      itemWrap: document.getElementById('item-wrap'),
      itemSlot: document.getElementById('item-slot'),
      itemIcon: document.getElementById('item-icon'),
      itemName: document.getElementById('item-name'),
      touchItemIcon: document.getElementById('touch-item-icon'),
      touchItemBtn: document.getElementById('btn-item'),
      message: document.getElementById('message'),
      messageMain: document.getElementById('message-main'),
      messageSub: document.getElementById('message-sub'),
      powerTag: document.getElementById('power-tag'),
      hitFlash: document.getElementById('hit-flash'),
      goalFlash: document.getElementById('goal-flash'),
      speedLines: document.getElementById('speed-lines'),
      minimap: document.getElementById('minimap'),
      touch: document.getElementById('touch-controls'),
      menu: document.getElementById('menu'),
      pause: document.getElementById('pause'),
      end: document.getElementById('end'),
      endTitle: document.getElementById('end-title'),
      endKicker: document.getElementById('end-kicker'),
      endBlue: document.getElementById('end-blue'),
      endRed: document.getElementById('end-red'),
      loading: document.getElementById('loading'),
      soundBtn: document.getElementById('sound-btn'),
    };
    this.ctx = this.el.minimap.getContext('2d');
    this.messageTimer = 0;
    this.messageToken = 0;
    this.lastScore = { blue: -1, red: -1 };
    this.callbacks = {};
    this.touchVisible = false;
    this.minimapTime = 0;
    this.bind();
  }

  on(name, fn) {
    this.callbacks[name] = fn;
  }

  bind() {
    const bind = (id, name) => {
      const el = document.getElementById(id);
      if (el) el.addEventListener('click', (event) => {
        event.preventDefault();
        this.callbacks[name]?.();
      });
    };
    bind('play-btn', 'play');
    bind('sound-btn', 'sound');
    bind('resume-btn', 'resume');
    bind('restart-btn', 'restart');
    bind('quit-btn', 'quit');
    bind('rematch-btn', 'rematch');
    bind('menu-btn', 'quit');
  }

  showLoading(show) {
    if (show) {
      this.el.loading.classList.remove('hidden', 'fade');
    } else {
      this.el.loading.classList.add('fade');
      setTimeout(() => this.el.loading.classList.add('hidden'), 500);
    }
  }

  showHUD(show) {
    this.el.hud.classList.toggle('hidden', !show);
    if (!show) this.el.touch.classList.add('hidden');
  }

  showTouch(show) {
    this.touchVisible = show;
    this.el.touch.classList.toggle('hidden', !show);
  }

  showMenu(show) {
    this.el.menu.classList.toggle('hidden', !show);
  }

  showPause(show) {
    this.el.pause.classList.toggle('hidden', !show);
  }

  showEnd(show) {
    this.el.end.classList.toggle('hidden', !show);
  }

  setSoundLabel(muted) {
    if (this.el.soundBtn) this.el.soundBtn.textContent = muted ? 'SOUND: OFF' : 'SOUND: ON';
  }

  setScore(blue, red) {
    if (blue !== this.lastScore.blue) {
      this.el.scoreBlue.textContent = blue;
      this.pulse(this.el.scoreBlue);
    }
    if (red !== this.lastScore.red) {
      this.el.scoreRed.textContent = red;
      this.pulse(this.el.scoreRed);
    }
    this.lastScore = { blue, red };
  }

  pulse(el) {
    el.animate(
      [{ transform: 'scale(1.55)', filter: 'brightness(2)' }, { transform: 'scale(1)', filter: 'brightness(1)' }],
      { duration: 420, easing: 'cubic-bezier(0.2, 1.4, 0.4, 1)' }
    );
  }

  update(game) {
    const { score, timeLeft, player } = game;
    this.setScore(score.blue, score.red);
    this.el.clock.textContent = formatTime(timeLeft);
    this.el.clock.classList.toggle('low', timeLeft <= 30 && game.state === 'playing');
    this.el.clockLabel.textContent = game.overtime ? 'OVERTIME' : 'TIME';

    if (player) {
      const boost = Math.round(player.boost);
      this.el.boostFill.style.width = `${boost}%`;
      this.el.boostNum.textContent = boost;
      const kmh = Math.round(player.speed * 3.6);
      this.el.speed.textContent = kmh;
      this.updateItem(player);
      this.updatePower(player);
      this.el.speedLines.style.opacity = String(clamp((player.speed - 24) / 40, 0, 0.55));
      if (this.el.touchItemBtn) this.el.touchItemBtn.style.setProperty('--boost', `${boost}%`);
    }

    this.minimapTime += 1;
    if (this.minimapTime % 2 === 0) this.drawMinimap(game);
  }

  updateItem(player) {
    const type = player.item;
    if (type) {
      const meta = ITEMS[type];
      this.el.itemSlot.classList.add('has-item');
      this.el.itemIcon.textContent = meta.icon;
      this.el.itemName.textContent = meta.name;
      if (this.el.touchItemIcon) this.el.touchItemIcon.textContent = meta.icon;
      this.el.touchItemBtn?.classList.add('has-item');
    } else {
      this.el.itemSlot.classList.remove('has-item');
      this.el.itemIcon.textContent = '?';
      this.el.itemName.textContent = 'EMPTY';
      if (this.el.touchItemIcon) this.el.touchItemIcon.textContent = '?';
      this.el.touchItemBtn?.classList.remove('has-item');
    }
  }

  updatePower(player) {
    let text = '';
    let cls = '';
    if (player.starTime > 0) {
      text = `STAR POWER · ${player.starTime.toFixed(1)}s`;
      cls = 'star';
    } else if (player.shrinkTime > 0) {
      text = `SHRUNK · ${player.shrinkTime.toFixed(1)}s`;
      cls = 'shrink';
    } else if (player.boostTime > 0) {
      text = `MUSHROOM BOOST · ${player.boostTime.toFixed(1)}s`;
      cls = 'star';
    }
    if (text) {
      this.el.powerTag.textContent = text;
      this.el.powerTag.className = `power-tag show ${cls}`;
    } else {
      this.el.powerTag.className = 'power-tag';
    }
  }

  message(main, sub = '', cls = '', duration = 1.6) {
    const token = ++this.messageToken;
    this.el.messageMain.textContent = main;
    this.el.messageMain.className = `message-main ${cls}`;
    this.el.messageSub.textContent = sub;
    this.el.message.classList.add('show');
    this.messageTimer = duration;
    this.messageToken = token;
    clearTimeout(this.messageTimeout);
    this.messageTimeout = setTimeout(() => {
      if (token === this.messageToken) this.el.message.classList.remove('show');
    }, duration * 1000);
  }

  flashHit() {
    this.el.hitFlash.classList.remove('flash-on');
    void this.el.hitFlash.offsetWidth;
    this.el.hitFlash.classList.add('flash-on');
  }

  flashGoal() {
    this.el.goalFlash.classList.remove('flash-on');
    void this.el.goalFlash.offsetWidth;
    this.el.goalFlash.classList.add('flash-on');
  }

  showEnd(winner, score) {
    const blueWin = winner === 'blue';
    this.el.endTitle.textContent = blueWin ? 'BLUE WINS' : 'RED WINS';
    this.el.endTitle.classList.toggle('red-win', !blueWin);
    this.el.endKicker.textContent = this.overtime ? 'GOLDEN GOAL' : 'FULL TIME';
    this.el.endBlue.textContent = score.blue;
    this.el.endRed.textContent = score.red;
    this.showEndScreen(true);
  }

  showEndScreen(show) {
    this.el.end.classList.toggle('hidden', !show);
  }

  drawMinimap(game) {
    const g = this.ctx;
    const w = this.el.minimap.width;
    const h = this.el.minimap.height;
    g.clearRect(0, 0, w, h);

    const pad = 14;
    const fieldW = w - pad * 2;
    const fieldH = h - pad * 2;
    const sx = fieldW / (ARENA.halfW * 2);
    const sz = fieldH / (ARENA.halfL * 2);
    const cx = w / 2;
    const cy = h / 2;

    g.fillStyle = 'rgba(4, 10, 24, 0.7)';
    g.beginPath();
    g.roundRect(4, 4, w - 8, h - 8, 12);
    g.fill();

    g.fillStyle = 'rgba(20, 72, 58, 0.55)';
    g.fillRect(cx - ARENA.halfW * sx, cy - ARENA.halfL * sz, ARENA.halfW * 2 * sx, ARENA.halfL * 2 * sz);

    g.strokeStyle = 'rgba(160, 220, 255, 0.4)';
    g.lineWidth = 1.5;
    g.strokeRect(cx - ARENA.halfW * sx, cy - ARENA.halfL * sz, ARENA.halfW * 2 * sx, ARENA.halfL * 2 * sz);

    g.beginPath();
    g.moveTo(cx - ARENA.halfW * sx, cy);
    g.lineTo(cx + ARENA.halfW * sx, cy);
    g.stroke();

    g.beginPath();
    g.arc(cx, cy, 16, 0, TAU);
    g.stroke();

    // goals
    g.fillStyle = 'rgba(61, 210, 255, 0.85)';
    g.fillRect(cx - ARENA.goalHalfW * sx, cy + ARENA.halfL * sz - 3, ARENA.goalHalfW * 2 * sx, 5);
    g.fillStyle = 'rgba(255, 64, 110, 0.85)';
    g.fillRect(cx - ARENA.goalHalfW * sx, cy - ARENA.halfL * sz - 2, ARENA.goalHalfW * 2 * sx, 5);

    // item boxes
    for (const box of game.items.boxes) {
      if (!box.active) continue;
      const x = cx + box.base.x * sx;
      const y = cy + box.base.z * sz;
      g.save();
      g.translate(x, y);
      g.rotate(Math.PI / 4);
      g.fillStyle = 'rgba(255, 220, 90, 0.9)';
      g.fillRect(-2.5, -2.5, 5, 5);
      g.restore();
    }

    // bananas
    for (const b of game.items.bananas) {
      g.fillStyle = 'rgba(255, 225, 74, 0.95)';
      g.beginPath();
      g.arc(cx + b.pos.x * sx, cy + b.pos.z * sz, 2.4, 0, TAU);
      g.fill();
    }

    // ball
    const bx = cx + game.ball.pos.x * sx;
    const by = cy + game.ball.pos.z * sz;
    g.beginPath();
    g.arc(bx, by, 5, 0, TAU);
    g.fillStyle = 'rgba(255, 255, 255, 0.25)';
    g.fill();
    g.beginPath();
    g.arc(bx, by, 3, 0, TAU);
    g.fillStyle = '#ffffff';
    g.fill();

    // cars
    for (const car of game.cars) {
      const x = cx + car.pos.x * sx;
      const y = cy + car.pos.z * sz;
      const color = car.team === 'blue' ? TEAM.blue.css : TEAM.red.css;
      g.save();
      g.translate(x, y);
      g.rotate(-car.yaw);
      g.fillStyle = color;
      g.beginPath();
      g.moveTo(0, -6);
      g.lineTo(4, 5);
      g.lineTo(0, 2.5);
      g.lineTo(-4, 5);
      g.closePath();
      g.fill();
      if (car.isPlayer) {
        g.strokeStyle = '#d9ff45';
        g.lineWidth = 1.8;
        g.beginPath();
        g.arc(0, 0, 8, 0, TAU);
        g.stroke();
      }
      g.restore();
    }

    g.fillStyle = 'rgba(150, 190, 230, 0.5)';
    g.font = '700 10px Chakra, sans-serif';
    g.textAlign = 'left';
    g.fillText('YOU', 10, h - 9);
    g.fillStyle = '#d9ff45';
    g.fillRect(36, h - 16, 8, 3);
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

import { ARENA, TEAM, MATCH, ITEMS } from './constants.js';
import { clamp, damp, formatTime, rand } from './utils.js';
import { buildWorld } from './world.js';
import { Ball } from './ball.js';
import { Car } from './car.js';
import { Effects } from './effects.js';
import { AudioEngine } from './audio.js';
import { Input } from './input.js';
import { HUD } from './hud.js';
import { ItemSystem } from './items.js';
import { AIController } from './ai.js';
import { isBallInGoal } from './physics.js';

class Game {
  constructor() {
    this.canvas = document.getElementById('game');
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: 'high-performance',
      stencil: false,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.8));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.06;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(66, window.innerWidth / window.innerHeight, 0.1, 700);
    this.camera.position.set(0, 24, 58);

    this.composer = new EffectComposer(this.renderer);
    this.composer.setPixelRatio(this.renderer.getPixelRatio());
    this.renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(this.renderPass);
    this.bloom = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.55,
      0.65,
      0.78
    );
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());

    this.effects = new Effects(this.scene, this.renderer);
    this.world = buildWorld(this.scene, this.renderer);
    this.audio = new AudioEngine();
    this.hud = new HUD();
    this.input = new Input();

    this.ball = new Ball(this.scene, this.renderer, this.effects, this.audio);
    this.items = new ItemSystem(this.scene, this.renderer, this.effects, this.audio, this.ball);

    this.player = new Car(this.scene, { team: 'blue', index: 0, name: 'YOU', isPlayer: true, effects: this.effects, audio: this.audio });
    this.teammate = new Car(this.scene, { team: 'blue', index: 1, name: 'BOLT', effects: this.effects, audio: this.audio });
    this.redA = new Car(this.scene, { team: 'red', index: 0, name: 'RAZOR', effects: this.effects, audio: this.audio });
    this.redB = new Car(this.scene, { team: 'red', index: 1, name: 'NOVA', effects: this.effects, audio: this.audio });
    this.cars = [this.player, this.teammate, this.redA, this.redB];

    this.player.onHit = () => this.hud.flashHit();

    this.state = 'menu';
    this.paused = false;
    this.score = { blue: 0, red: 0 };
    this.timeLeft = MATCH.duration;
    this.overtime = false;
    this.pendingEnd = false;
    this.countdown = 0;
    this.lastCount = 4;
    this.goalTimer = 0;
    this.goalTeam = null;
    this.goalPosition = new THREE.Vector3();
    this.matchTime = 0;
    this.accumulator = 0;
    this.step = 1 / 90;
    this.cameraSnap = true;
    this.lookTarget = new THREE.Vector3(0, 2, 0);
    this.jumboTimer = 0;
    this.firstFrame = true;
    this.fpsTime = 0;
    this.fpsFrames = 0;
    this.lowQuality = false;
    this.isCoarse = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;

    this.ai = [
      new AIController(this.teammate, this, 0.84, 12),
      new AIController(this.redA, this, 0.8, 31),
      new AIController(this.redB, this, 0.86, 57),
    ];

    this.items.on('pickup', (car, type) => {
      if (car === this.player) {
        const meta = ITEMS[type];
        this.hud.message(`${meta.icon}  ${meta.name}`, 'ITEM ACQUIRED', 'lime', 0.9);
      }
    });
    this.items.on('use', (car, type) => {
      if (car === this.player && type === 'lightning') {
        this.hud.flashGoal();
        this.effects.addShake(0.4);
      }
    });

    this.hud.on('play', () => this.startMatch());
    this.hud.on('sound', () => {
      this.audio.init();
      const muted = this.audio.toggleMuted();
      this.hud.setSoundLabel(muted);
      if (!muted) this.audio.click();
    });
    this.hud.on('resume', () => this.togglePause(false));
    this.hud.on('restart', () => {
      this.paused = false;
      this.hud.showPause(false);
      this.startMatch();
    });
    this.hud.on('quit', () => this.toMenu());
    this.hud.on('rematch', () => this.startMatch());

    this.input.on('pause', () => this.togglePause());
    this.input.on('ballcam', (on) => {
      if (this.state === 'playing' || this.state === 'countdown') {
        this.hud.message(on ? 'BALL CAM ON' : 'BALL CAM OFF', '', '', 0.7);
      }
    });
    this.input.on('confirm', () => {
      if (this.state === 'menu') this.startMatch();
      else if (this.state === 'ended') this.startMatch();
    });

    this.setupFormation();
    this.hud.showHUD(false);
    this.hud.showMenu(true);
    this.hud.showTouch(false);
    this.hud.setSoundLabel(this.audio.muted);

    window.addEventListener('resize', () => this.resize());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing' && !this.paused) this.togglePause(true);
    });

    this.clock = new THREE.Clock();
    this.animate = this.animate.bind(this);
    requestAnimationFrame(this.animate);

    window.__game = this;
  }

  resize() {
    const w = window.innerWidth;
    const h = window.innerHeight;
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(w, h);
    this.composer.setSize(w, h);
    this.bloom.setSize(w, h);
  }

  setupFormation() {
    this.ball.reset();
    this.player.reset(-5, 29, Math.PI);
    this.teammate.reset(6.5, 33, Math.PI);
    this.redA.reset(5, -29, 0);
    this.redB.reset(-6.5, -33, 0);
    this.items.reset();
    this.items.enabled = false;
    this.cameraSnap = true;
  }

  startMatch() {
    this.audio.init();
    this.audio.click();
    this.score.blue = 0;
    this.score.red = 0;
    this.timeLeft = MATCH.duration;
    this.overtime = false;
    this.pendingEnd = false;
    this.paused = false;
    this.hud.showMenu(false);
    this.hud.showEndScreen(false);
    this.hud.showPause(false);
    this.hud.showHUD(true);
    this.syncTouch();
    this.setupFormation();
    this.beginKickoff();
    this.hud.setScore(0, 0);
  }

  beginKickoff() {
    this.state = 'countdown';
    this.countdown = 3.2;
    this.lastCount = 4;
    this.items.enabled = false;
    this.cameraSnap = true;
    this.syncTouch();
  }

  startOvertime() {
    this.overtime = true;
    this.timeLeft = 0;
    this.pendingEnd = false;
    this.setupFormation();
    this.state = 'countdown';
    this.countdown = 3.2;
    this.lastCount = 4;
    this.items.enabled = false;
    this.cameraSnap = true;
    this.audio.whistle();
    this.hud.message('OVERTIME', 'NEXT GOAL WINS', 'lime', 2.2);
    this.syncTouch();
  }

  endMatch() {
    this.state = 'ended';
    this.paused = false;
    this.items.enabled = false;
    this.hud.showTouch(false);
    const winner = this.score.blue > this.score.red ? 'blue' : 'red';
    this.hud.overtime = this.overtime;
    this.hud.showEnd(winner, this.score);
    this.audio.whistle();
    this.audio.cheer(1.1);
    this.cameraSnap = true;
  }

  toMenu() {
    this.state = 'menu';
    this.paused = false;
    this.score.blue = 0;
    this.score.red = 0;
    this.timeLeft = MATCH.duration;
    this.overtime = false;
    this.pendingEnd = false;
    this.hud.showHUD(false);
    this.hud.showMenu(true);
    this.hud.showPause(false);
    this.hud.showEndScreen(false);
    this.hud.showTouch(false);
    this.audio.setEngine(0, false, 0, false);
    this.setupFormation();
    this.cameraSnap = true;
  }

  togglePause(force) {
    if (this.state === 'menu' || this.state === 'ended') return;
    const next = typeof force === 'boolean' ? force : !this.paused;
    this.paused = next;
    this.hud.showPause(next);
    this.syncTouch();
    if (next) this.audio.setEngine(0, false, 0, false);
    this.audio.click();
  }

  syncTouch() {
    const show = this.isCoarse && !this.paused && (this.state === 'playing' || this.state === 'countdown' || this.state === 'goal');
    this.hud.showTouch(show);
  }

  scoreGoal(side) {
    const scorer = side === 1 ? 'red' : 'blue';
    const team = TEAM[scorer];
    const other = TEAM[scorer === 'blue' ? 'red' : 'blue'];
    this.score[scorer] += 1;
    this.state = 'goal';
    this.goalTeam = scorer;
    this.goalTimer = MATCH.goalCelebration;
    this.goalPosition.copy(this.ball.pos);
    this.items.enabled = false;
    this.pendingEnd = this.timeLeft <= 2.2 || this.overtime;
    this.hud.message(`${team.name} GOAL!`, `${this.score.blue} — ${this.score.red}`, scorer, 3);
    this.hud.flashGoal();
    this.hud.setScore(this.score.blue, this.score.red);
    this.effects.goal(this.goalPosition.clone().add(new THREE.Vector3(0, 1, 0)), team.color, other.color);
    this.audio.goal();
    this.effects.addShake(0.7);
    this.syncTouch();
    if (this.overtime) this.hud.message(`${team.name} WINS!`, 'GOLDEN GOAL', scorer, 3);
  }

  updateCountdown(dt) {
    this.countdown -= dt;
    const n = Math.ceil(this.countdown);
    if (n !== this.lastCount && n > 0 && n <= 3) {
      this.lastCount = n;
      this.hud.message(String(n), this.overtime ? 'OVERTIME' : 'KICKOFF', 'lime', 0.95);
      this.audio.countdown(n === 1);
    }
    if (this.countdown <= 0) {
      this.state = 'playing';
      this.items.enabled = true;
      this.hud.message('GO!', '', 'lime', 0.8);
      this.audio.go();
      this.syncTouch();
      this.cameraSnap = false;
    }
  }

  updateGoal(dt) {
    this.goalTimer -= dt;
    // let the ball settle and cars coast for a lively celebration
    for (const car of this.cars) {
      car.controls.throttle = 0;
      car.controls.steer = 0;
      car.controls.boost = false;
      car.controls.jump = false;
      car.controls.item = false;
      car.update(dt, this.matchTime);
    }
    this.ball.update(dt, this.cars);
    this.effects.addShake(0);
    if (this.goalTimer <= 0) {
      if (this.pendingEnd) {
        if (this.score.blue === this.score.red) this.startOvertime();
        else this.endMatch();
      } else {
        this.setupFormation();
        this.beginKickoff();
      }
    }
  }

  updateGameplay(dt) {
    const controls = this.input.getControls();
    Object.assign(this.player.controls, controls);

    for (const ai of this.ai) ai.update(dt, this.matchTime);

    this.items.update(dt, this.matchTime, this.cars);

    for (const car of this.cars) car.update(dt, this.matchTime);

    // car-car collisions and star ramming
    for (let i = 0; i < this.cars.length; i++) {
      for (let j = i + 1; j < this.cars.length; j++) {
        const a = this.cars[i];
        const b = this.cars[j];
        const dx = b.pos.x - a.pos.x;
        const dz = b.pos.z - a.pos.z;
        const dist2 = dx * dx + dz * dz;
        if (dist2 > 3.1 * 3.1) continue;
        if (a.starTime > 0 || b.starTime > 0) {
          if (a.starTime > 0 && b.starTime <= 0) {
            const dir = new THREE.Vector3(dx, 0, dz).normalize();
            if (b.takeHit(dir, 1.4)) {
              this.effects.hit(b.pos.clone().add(new THREE.Vector3(0, 1, 0)), 0xffe14a);
              if (b.isPlayer) this.hud.flashHit();
            }
          } else if (b.starTime > 0 && a.starTime <= 0) {
            const dir = new THREE.Vector3(-dx, 0, -dz).normalize();
            if (a.takeHit(dir, 1.4)) {
              this.effects.hit(a.pos.clone().add(new THREE.Vector3(0, 1, 0)), 0xffe14a);
              if (a.isPlayer) this.hud.flashHit();
            }
          }
        }
        if (dist2 > 0.0001) {
          const dist = Math.sqrt(dist2);
          const nx = dx / dist;
          const nz = dz / dist;
          const overlap = 3.1 - dist;
          a.pos.x -= nx * overlap * 0.5;
          a.pos.z -= nz * overlap * 0.5;
          b.pos.x += nx * overlap * 0.5;
          b.pos.z += nz * overlap * 0.5;
          const rvx = b.vel.x - a.vel.x;
          const rvz = b.vel.z - a.vel.z;
          const vn = rvx * nx + rvz * nz;
          if (vn < 0) {
            a.vel.x -= nx * vn * 0.35;
            a.vel.z -= nz * vn * 0.35;
            b.vel.x += nx * vn * 0.35;
            b.vel.z += nz * vn * 0.35;
            if ((a.isPlayer || b.isPlayer) && Math.abs(vn) > 7) this.effects.addShake(0.2);
          }
        }
      }
    }

    // boost pads
    for (const car of this.cars) {
      if (car.pos.y > 2.4) continue;
      for (const pad of this.world.pads) {
        if (!pad.active) continue;
        const dx = car.pos.x - pad.pos.x;
        const dz = car.pos.z - pad.pos.z;
        if (dx * dx + dz * dz < (pad.radius + 1.5) ** 2) {
          if (pad.collect()) {
            car.boost = Math.min(100, car.boost + (pad.big ? 100 : 12));
            this.effects.burst(new THREE.Vector3(pad.pos.x, 0.6, pad.pos.z), pad.big ? 0xffd24a : 0xff9a2e, pad.big ? 18 : 8, { speed: 5, size: 0.7, life: 0.4, gravity: 0 });
            if (car.isPlayer) this.audio.pickup();
          }
        }
      }
    }

    this.ball.update(dt, this.cars);

    if (this.player.itemPressed && this.player.item) {
      this.items.useItem(this.player, this.cars);
    }

    const side = isBallInGoal(this.ball);
    if (side !== 0 && this.state === 'playing') {
      this.scoreGoal(side);
      return;
    }
  }

  updateCamera(dt) {
    const time = this.matchTime;
    let desired = new THREE.Vector3();
    let look = new THREE.Vector3();
    let snap = this.cameraSnap;

    if (this.state === 'menu') {
      const angle = time * 0.11;
      desired.set(Math.cos(angle) * 48, 23 + Math.sin(time * 0.25) * 2, Math.sin(angle) * 48);
      look.set(0, 3, 0);
      this.camera.fov = damp(this.camera.fov, 54, 2, dt);
    } else if (this.state === 'ended') {
      const angle = time * 0.2;
      desired.set(Math.cos(angle) * 38, 18, Math.sin(angle) * 38);
      look.copy(this.ball.pos).setY(3);
      this.camera.fov = damp(this.camera.fov, 56, 2, dt);
    } else if (this.state === 'goal') {
      const angle = time * 0.65;
      desired.set(this.goalPosition.x + Math.cos(angle) * 17, 9.5 + Math.sin(angle * 0.8) * 2, this.goalPosition.z + Math.sin(angle) * 17);
      look.copy(this.goalPosition).add(new THREE.Vector3(0, 1.5, 0));
      this.camera.fov = damp(this.camera.fov, 62, 3, dt);
      snap = true;
    } else {
      const player = this.player;
      const forward = player.forward;
      const speed = player.speed;
      const back = 13.6 + speed * 0.055;
      desired.set(
        player.pos.x - forward.x * back,
        6.6 + speed * 0.02,
        player.pos.z - forward.z * back
      );
      look.set(player.pos.x + forward.x * 5.5, player.pos.y + 2.4, player.pos.z + forward.z * 5.5);
      if (this.input.ballCam) look.lerp(this.ball.pos, 0.6);
      const boosting = player.boosting || player.boostTime > 0 || player.starTime > 0;
      const targetFov = 66 + Math.min(16, speed * 0.28) + (boosting ? 5 : 0);
      this.camera.fov = damp(this.camera.fov, targetFov, 3.5, dt);
    }

    this.camera.updateProjectionMatrix();

    if (snap) {
      this.camera.position.copy(desired);
      this.lookTarget.copy(look);
      this.cameraSnap = false;
    } else {
      this.camera.position.lerp(desired, 1 - Math.exp(-5.2 * dt));
      this.lookTarget.lerp(look, 1 - Math.exp(-7 * dt));
    }

    const shake = this.effects.getShake(time);
    this.camera.position.x += shake.x;
    this.camera.position.y += shake.y;
    this.camera.lookAt(this.lookTarget);
    this.camera.rotation.z += shake.roll;
  }

  animate() {
    requestAnimationFrame(this.animate);
    const rawDt = this.clock.getDelta();
    const dt = clamp(rawDt, 0.001, 0.05);
    if (!this.paused) {
      this.matchTime += dt;
      this.world.update(dt, this.matchTime);

      if (this.state === 'countdown') {
        this.updateCountdown(dt);
      } else if (this.state === 'playing') {
        if (!this.overtime) {
          this.timeLeft = Math.max(0, this.timeLeft - dt);
        }
        this.accumulator += dt;
        let steps = 0;
        while (this.accumulator >= this.step && steps < 6) {
          this.updateGameplay(this.step);
          this.accumulator -= this.step;
          steps++;
          if (this.state !== 'playing') break;
        }
        if (this.state === 'playing' && this.timeLeft <= 0 && !this.overtime) {
          if (this.score.blue === this.score.red) this.startOvertime();
          else this.endMatch();
        }
      } else if (this.state === 'goal') {
        this.updateGoal(dt);
      }

      this.effects.update(dt, this.matchTime);
    }

    if (this.state === 'menu' || this.state === 'ended') {
      // subtle ball idle animation
      this.ball.mesh.rotation.y += dt * 0.15;
      this.ball.glow.material.opacity = 0.2 + Math.sin(this.matchTime * 2) * 0.05;
    }

    this.updateCamera(dt);

    this.hud.update(this);
    this.jumboTimer -= dt;
    if (this.jumboTimer <= 0) {
      this.jumboTimer = 0.4;
      let label = 'READY';
      if (this.state === 'countdown') label = this.overtime ? 'OVERTIME' : 'KICKOFF';
      else if (this.state === 'playing') label = this.overtime ? 'OVERTIME' : 'LIVE';
      else if (this.state === 'goal') label = 'GOAL!';
      else if (this.state === 'ended') label = 'FULL TIME';
      else if (this.state === 'menu') label = 'WARM UP';
      this.world.setScore(this.score.blue, this.score.red, formatTime(this.timeLeft), label);
    }

    const active = this.state === 'playing' && !this.paused;
    this.audio.setEngine(this.player.speed, this.player.boosting || this.player.boostTime > 0, this.player.controls.throttle, active);

    this.composer.render();

    if (this.firstFrame) {
      this.firstFrame = false;
      this.hud.showLoading(false);
    }

    // adaptive quality for software renderers / weaker phones
    this.fpsTime += dt;
    this.fpsFrames++;
    if (this.fpsTime > 3.5) {
      const fps = this.fpsFrames / this.fpsTime;
      if (fps < 45 && !this.lowQuality) {
        this.lowQuality = true;
        this.bloom.enabled = false;
        this.renderer.setPixelRatio(1);
        this.composer.setPixelRatio(1);
        this.resize();
      }
      this.fpsTime = 0;
      this.fpsFrames = 0;
    }
  }
}

async function boot() {
  try {
    await document.fonts.ready;
    new Game();
  } catch (error) {
    console.error(error);
    const loading = document.getElementById('loading');
    if (loading) {
      loading.innerHTML = `<div class="loader-logo">SHELL<span>STRIKERS</span></div><div class="loader-text">COULD NOT START: ${String(error.message || error)}</div>`;
    }
  }
}

boot();

